// Scene 1 inspired by Walter Franzen, Der rote Klecks
function createScene1() {
	const w_3 = width / 3;
	const h_3 = height / 3;

	// splatter lines
	const pts = [{x: 0, y: -h_3 * random(0.7,1)}, {x: 3, y: 0}, {x: 0, y: h_3 * random(0.7,1)}, {x: -3, y: 0}];
	spltrs.push(new Splatter(w_3, 2 * h_3, 20, pltDark[0]));
	let spltrLine = spltrs[spltrs.length - 1];
	spltrLine.setPts(pts);
	spltrs.push(new Splatter(w_3 / 2, height / 2, 20, pltDark[1]));
	spltrLine = spltrs[spltrs.length - 1];
	spltrLine.setPts(pts);

	// gray + black splatters vert
	const dirV = [createVector(0, 0.45), createVector(0, -0.45)];
	for (let i = 0; i < 100; i++) {
		const sze = random(10, max(width, height) * 0.05);
		const cI =  min(floor(random(pltDark.length) * 0.75), pltDark.length - 1);
		const y = random(height);
		const dst = abs(y - h_3);
		if (random() < (dst / h_3)) {
			spltrs.push(new Splatter(w_3 / (cI + 1), y, sze, pltDark[cI], dirV[cI])); // random(pltDark)
		}
	}

	// center red
	for (let i = 0; i < 20; i++) {
		var sze = random(max(width, height) * 0.1, max(width, height) * 0.25);
		const x = randomGaussian(w_3, 75);
		var y = randomGaussian(h_3, 75);
		var dst = dist(x, y, w_3, h_3);
		sze = map(dst, 0, 200, sze, 10)
		spltrs.push(new Splatter(x, y, sze, "darkred")); // random(pltRed)
	}
}

// Scene 2: random plt from palette[], all same direction
function createScene2() {
	let plt = [];
	const n = random(1, 10);
	for (let i = 0; i < n; i++) plt.push(random(palette));
	plt = palette;

	var dirV = p5.Vector.random2D(); // all same direction
	for (let i = 0; i < random(2, 20); i++) {
		spltrs.push(new Splatter(random(width), random(height), random(10, max(width, height) * 0.2), random(plt), dirV));
		spltrs[spltrs.length-1].createSplatterFrom(spltrs, floor(random(2,5)));
	}
}

// Scene 3: 2 big splatters, 3 lines of splatetrs
function createScene3() {
	for (let i = 0; i < 2; i++) {
		spltrs.push(new Splatter(random(width), random(height), random(10, max(width, height) * 0.3), random(palette)));
		spltrs[spltrs.length-1].createSplatterFrom(spltrs, floor(random(2,5)));
	}

	var n = 5;
	for (let i = 0; i < n; i++) {
		var x =(i + 1) / (n + 2) * width;
		spltrs.push(new Splatter(x, height/2, max(width, height) * 0.05, random(palette)));
		var dirV = createVector(0.97, 0);
		let rndCol = random(palette);
		spltrs.push(new Splatter(x, height/3, max(width, height) * 0.05, rndCol, dirV));
		spltrs.push(new Splatter(x, height/3, max(width, height) * 0.05, rndCol, dirV));
		spltrs.push(new Splatter(x, height/3, max(width, height) * 0.05, rndCol, dirV));
		dirV = createVector(-0.97, 0);
		spltrs.push(new Splatter(x, height*2/3, max(width, height) * 0.05, random(palette), dirV));
	}
}

