/**
 * Splatter class
 */
class Splatter {
	constructor(_x, _y, _r, _c, _d) {
		this.x = _x; // center x
		this.y = _y; // center y
		this.r = _r; // radius

		this.c = this.randomizeColor(_c, 5); // slightly deviation of color
		// this.c = color(_c);
		this.c.setAlpha(160);

		this.d = _d || createVector(0.0, 0.0); // dir
		this.n = floor(random(7, 17)); //  num edges
		this.generatePts();
	}

	// create sub splatters recursive
	createSplatterFrom(array, num) {
		if (num <= 0) return;

		const dA = PI / 8; // deltaAngle
		// create small dir change
		for (let i = 0; i < 3; i++) {
			// only folllow path by 50%
			if (random() < 0.5) {
				// follow new path
				var dirV = this.d.copy();
				dirV.rotate(random(-dA, dA));
				var x = this.x + cos(dirV.heading()) * this.r * 3;
				var y = this.y + sin(dirV.heading()) * this.r * 3;
				let r = this.r * 0.5;
				let newSplatter = new Splatter(x, y, r, this.c, dirV);
				array.push(newSplatter);
				newSplatter.createSplatterFrom(array, num - 1);
			}
		}
	}

	setPts(_p) {
		this.pts = _p
	}

	generatePts(_d) {
		if (_d) this.d = _d;
		this.pts = [];

		const d = 5;
		const da = 1 / this.n * TWO_PI / 2;
		// rotate(random(da));

		let a = this.d.heading();
		let sx, sy;
		// generate "star" points with different radius to curve between points
		for (let i = 0; i < this.n; i++) {
			// deviate points from outer radius
			let dx = random(-d, d);
			let dy = random(-d, d);

			let dr = random(0.75, 1.25);
			var x = dx + cos(a) * this.r * dr;
			var y = dy + sin(a) * this.r * dr;

			let p = this.sclValues(x, y, this.r, this.d);

			// remember starting point to end with it
			if (i == 0) sx = p.x, sy = p.y;

			this.pts.push({x: p.x, y: p.y});
			this.pts.push({x: p.x, y: p.y});
			a += da;

			// generate points for inner radius
			dr = random(0.5, 1.25);
			x = cos(a) * this.r * dr / 2;
			y = sin(a) * this.r * dr / 2;

			p = this.sclValues(x, y, this.r, this.d);
			this.pts.push({x: p.x, y: p.y});
			a += da;
		}
		this.pts.push({x: sx, y: sy});
	}

	show() {
		push();
		translate(this.x, this.y);
		noStroke();
		fill(this.c);

		// rotate(random(da));
		beginShape();
		for (let p of this.pts) {
			curveVertex(p.x, p.y);
		}
		endShape(CLOSE);		
		pop();
	}

	sclValues(_x, _y, _r, _vec) {
		let angle = _vec.angleBetween(createVector(_x, _y));
		if (isNaN(angle)) angle = 0;
		let scl = _vec.limit(1).mag();
  	scl *= (1 - abs(angle)/PI);
  	scl += 1;
		var x = _x + _r * _vec.x;
		var y = _y + _r * _vec.y;
		x *= scl;
		y *= scl;
		return {x, y};
	}

	randomizeColor(_c, _d = 10) {
		let clr = color(_c); // color(this.c);

		var r = red(window.color(clr)) + random(-_d, _d);
		let g = green(window.color(clr)) + random(-_d, _d);
		let b = blue(window.color(clr)) + random(-_d, _d);

		return color(r, g, b, 160);
		// return this.c;
	}
}

class Grain {
	constructor() {
		this.x = random(width)
		this.y = random(height)
		this.w = random(1, 5)
		this.b = random(0.5, 2);
	}

	show() {
		strokeWeight(this.b);
		if (random() < 0.51) line(this.x, this.y, this.x + this.w, this.y)	
		if (random() < 0.051) circle(this.x, this.y, random(height))	
	}
}
